import 'package:flutter/material.dart';
import 'package:priceshield/core/services/priceshield_api_client.dart';
import 'package:priceshield/features/complaints/presentation/screens/complaint_screen.dart';
class ScanDetailsScreen extends StatelessWidget { const ScanDetailsScreen({super.key, required this.scanData}); final Map<String, dynamic> scanData;
  @override Widget build(BuildContext context) { final name = scanData['productName']?.toString() ?? scanData['product_name']?.toString() ?? 'Product'; final barcode = scanData['barcode']?.toString() ?? ''; final mrp = num.tryParse('${scanData['mrp'] ?? 0}') ?? 0; final charged = num.tryParse('${scanData['chargedPrice'] ?? scanData['charged_price'] ?? 0}') ?? 0; final overcharged = charged > mrp; return Scaffold(appBar: AppBar(title: const Text('Scan Details')), body: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(name, style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 10), Text('Barcode: $barcode'), Text('MRP: ₹$mrp'), Text('Charged: ₹$charged'), Text(overcharged ? 'Overcharged by ₹${charged - mrp}' : 'Within MRP'), const Spacer(), if (overcharged) FilledButton(onPressed: () async { try { final complaints = await priceShieldApi.listComplaints(limit: 100); if (complaints.any((item) => item['barcode']?.toString() == barcode && item['status'] != 'WITHDRAWN')) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('A complaint for this product already exists.'))); return; } if (context.mounted) Navigator.push(context, MaterialPageRoute(builder: (_) => ComplaintScreen(name: name, barcode: barcode, mrp: mrp.toInt(), charged: charged.toInt()))); } on PriceShieldApiException catch (error) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.message))); } }, child: const Text('File a Complaint'))]))); }
}
